from collections import Counter

def transform(grid):
    H, W = len(grid), len(grid[0])

    # Find separator rows and columns (full rows/cols of one value)
    sep_rows = set()
    sep_cols = set()

    for r in range(H):
        if all(grid[r][c] == grid[r][0] for c in range(W)):
            sep_rows.add(r)

    for c in range(W):
        if all(grid[r][c] == grid[0][c] for r in range(H)):
            sep_cols.add(c)

    # Build bands
    r_seps = sorted(sep_rows)
    c_seps = sorted(sep_cols)

    r_bands = []
    curr = 0
    for s in r_seps:
        r_bands.append((curr, s))
        curr = s + 1
    r_bands.append((curr, H))

    c_bands = []
    curr = 0
    for s in c_seps:
        c_bands.append((curr, s))
        curr = s + 1
    c_bands.append((curr, W))

    h_out = len(r_bands)
    w_out = len(c_bands)

    # Collect all non-separator values
    vals = []
    for r in range(H):
        for c in range(W):
            if r not in sep_rows and c not in sep_cols:
                vals.append(grid[r][c])

    cnt = Counter(vals)
    bg_val = min(cnt.keys(), key=lambda k: cnt[k])

    # Build output
    res = []
    for i in range(h_out):
        row_res = []
        r_start, r_end = r_bands[i]
        for j in range(w_out):
