            # Find feature pixels (not separator val, not background)
            # Separator value is the one used for rows/cols (2, 9, etc.)
            sep_v = grid[r_seps[0]][0] if sep_rows else grid[0][0]

            features = []
            for r in range(r_start, r_end):
                for c in range(c_start, c_end):
                    if grid[r][c] != sep_v and grid[r][c] != bg_val:
                        features.append((r - r_start, c - c_start))

            if len(features) == 2:
                (r1, c1), (r2, c2) = features
                if abs(r1 - r2) > 1:
                    row_res.append(1)
                else:
                    row_res.append(bg_val)
            else:
                row_res.append(bg_val)
        res.append(row_res)

    return res
